package rustanything;

import java.lang.reflect.Type;
import java.util.*;

/** Generated by rust-anything: calls the Rust port of `backup/` through JNI. */
public final class BackupCoreRsNative {
    private BackupCoreRsNative() {}

    static {
        String path = System.getProperty("rust-anything.lib.backup_core_rs");
        if (path != null) {
            System.load(path);
        } else {
            System.loadLibrary("backup_core_rs");
        }
    }

    private static native String call(String name, String args);

    // Typed methods: primitives and strings cross JNI directly, without JSON.
    public static native String n_inspectBackupJson(String rawJson, String[] slot);
    public static native String n_mergeBackupConfigJson(String currentJson, String importedJson, boolean replaceAll, String[] slot);

    public static String call_inspectBackupJson(String rawJson) {
        try {
            String[] slot = RustAnythingError.slot();
            String out = n_inspectBackupJson(rawJson, slot);
            RustAnythingError.check(slot);
            return out;
        } catch (RustAnythingError e) {
            throw e.real();
        }
    }

    public static String call_mergeBackupConfigJson(String currentJson, String importedJson, boolean replaceAll) {
        try {
            String[] slot = RustAnythingError.slot();
            String out = n_mergeBackupConfigJson(currentJson, importedJson, replaceAll, slot);
            RustAnythingError.check(slot);
            return out;
        } catch (RustAnythingError e) {
            throw e.real();
        }
    }


    /** Calls the port of {@code name}; its answer is converted to {@code type}. */
    public static Object invoke(String name, Type type, Object... args) {
        String answer = call(name, RustAnythingJson.write(java.util.Arrays.asList(args)));
        @SuppressWarnings("unchecked")
        Map<String, Object> parsed = (Map<String, Object>) RustAnythingJson.parse(answer);
        if (parsed.containsKey("ok")) {
            return type == void.class ? null : RustAnythingJson.convert(parsed.get("ok"), type);
        }
        String message = parsed.containsKey("error")
            ? String.valueOf(parsed.get("error"))
            : "Rust panic: " + parsed.get("panic");
        throw exception(message);
    }

    /** {@code "IllegalArgumentException: msg"} becomes that exception; anything else a RuntimeException. */
    private static RuntimeException exception(String message) {
        int colon = message.indexOf(": ");
        if (colon > 0) {
            String type = message.substring(0, colon);
            String rest = message.substring(colon + 2);
            for (String prefix : new String[] {"", "java.lang.", "java.util.", "java.io.", "java.time."}) {
                try {
                    Class<?> c = Class.forName(prefix + type);
                    if (RuntimeException.class.isAssignableFrom(c)) {
                        return (RuntimeException) c.getConstructor(String.class).newInstance(rest);
                    }
                } catch (ReflectiveOperationException e) {
                    // try the next package
                }
            }
        }
        return new RuntimeException(message);
    }
}
